python3 -c "
import json
d=json.load(open('evidence/runs/angular-super-productivity-v2-13-15/u18d-capability-round.json'))
def walk(o,p=''):
    if isinstance(o,dict):
        for k,v in o.items():
            if isinstance(v,(dict,list)): walk(v,p+'/'+k)
            else: print(p+'/'+k, '=', str(v)[:200])
    elif isinstance(o,list):
        print(p,'[list len',len(o),']')
        for i,v in enumerate(o[:60]): walk(v,p+f'[{i}]')
walk(d)
" | head -200

