export function renameDeclaredTypeMembers(
	path: string,
	source: string,
	diagnostics: readonly MissingMemberDiagnostic[],
	renames: readonly DocumentedMemberRename[],
	surfaces: readonly TypeMemberSurfaceReading[],
): MemberRenameMigration {
