const MISSING_PROPERTY = createRegExp(
	exactly("Property '")
		.and(oneOrMore(charNotIn("'")).as('member'))
		.and(exactly("' does not exist on type '"))
		.and(oneOrMore(charNotIn("'")).as('type'))
		.and(exactly("'.")),
